import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`nail-salon-audit`,heroTitle:`Audit your nail salon in minutes`,heroSubtitle:`Perplexity Computer reviews your nail salon website, booking flow, reviews, and local visibility, then gives you a prioritized plan to win more appointments.`,inputUrlCta:`Audit my nail salon`,inputUrlPlaceholder:`yournailsalon.com`,inputUrlPrefill:`Go to {url} and run a full digital audit for this nail salon. 1) Review the website for service clarity, nail art portfolio quality, pricing visibility, mobile UX, and booking friction. 2) Audit the Google Business Profile, reviews, local SEO, and social proof. 3) Compare against top nearby nail salons for offers, service packaging, visual trust signals, and appointment CTAs. 4) Recommend the highest-impact changes for more bookings, repeat visits, and local search visibility. 5) Deliver a prioritized action plan with rewritten copy, booking-flow fixes, and growth recommendations.`,heroOverlaySteps:[`Reviewing your nail salon site, service menu, gallery, and booking path`,`Benchmarking nearby salons on reviews, offers, and local visibility`,`Finding the copy, trust, and mobile UX gaps holding back appointments`,`Booking fixes, local SEO priorities, and service messaging ready to use`],generatingSteps:[`Visiting {url} to inspect your nail salon website and booking experience`,`Designing an agent to compare nearby salons, reviews, and local search signals`,`Configuring service copy rewrites, offer recommendations, and conversion fixes`,`Setting up a prioritized action plan for appointment growth`],featureSectionTitle:`From casual browsers to booked chairs`,featureCardTitles:[`Connects to your salon stack`,`Fixes you can launch now`],featureCardDescriptions:[`Computer separates your nail salon audit into site review, service positioning, local SEO, and competitor research, then routes each step to the right model.`,`Google Business Profile, booking pages, Docs, Sheets, and planning tools can all feed one workflow so your team can move from analysis to execution.`,`Homepage rewrites. Booking-flow improvements. Review-response guidance. Local SEO priorities. Computer gives you updates tied to more appointments.`],capabilitySectionTitle:`Your nail salon growth team, on autopilot`,capabilitySectionSubtitle:`Paste your nail salon URL, step away, and come back to a clear plan to drive more bookings.`,capabilityCards:[{title:`Website Audit`,description:`Computer can review your service pages, nail art gallery, pricing clarity, booking flow, and mobile UX to find conversion gaps.`},{title:`Local Search Review`,description:`Computer can assess your Google Business Profile, review reputation, and local SEO setup to show where nearby salons are winning.`},{title:`Service Positioning`,description:`Computer can rewrite service messaging, CTA language, and promotional framing so prospects understand why to book now.`},{title:`Connect Your Tools`,description:`Computer can organize recommendations across Google Business Profile, booking tools, Docs, and Sheets so your team can execute quickly.`},{title:`Remember Your Services`,description:`Computer can remember your manicure, pedicure, nail art, and membership offers so future audits start with the right context.`},{title:`Monitor Booking Signals`,description:`Computer can revisit your online presence over time, flag when conversion signals slip, and suggest the next fix most likely to improve bookings.`}]});export{t as default};
